<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\Hash;
class AuthController extends Controller { public function showLogin(){if(Auth::check()&&Auth::user()->is_admin)return redirect()->route('admin.dashboard');return view('admin.auth.login');} public function login(Request $request){$cred=$request->validate(['email'=>'required|email','password'=>'required']); if(Auth::attempt($cred,$request->boolean('remember')) && Auth::user()->is_admin){$request->session()->regenerate();return redirect()->intended(route('admin.dashboard'));} Auth::logout();return back()->withErrors(['email'=>'Invalid administrator credentials.'])->onlyInput('email');} public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('admin.login');} public function profile(){return view('admin.profile');} public function updateProfile(Request $r){$u=$r->user();$data=$r->validate(['name'=>'required|max:120','email'=>'required|email|max:190|unique:users,email,'.$u->id,'current_password'=>'nullable|required_with:password','password'=>'nullable|min:8|confirmed']); if(!empty($data['password'])){if(!Hash::check($data['current_password'],$u->password))return back()->withErrors(['current_password'=>'Current password is incorrect.']);$u->password=$data['password'];}$u->name=$data['name'];$u->email=$data['email'];$u->save();return back()->with('success','Profile updated.');} }
